using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Mavis;
public static class AutoQaWarningContracts{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);static void Prop(object o,string n,object v)=>o.GetType().GetProperty(n).SetValue(o,v);static void Call(object o,string n,params object[] v)=>o.GetType().GetMethod(n,F).Invoke(o,v);
 public static object Run(string take){if(!Application.isPlaying||SceneManager.sceneCount!=1||!string.IsNullOrEmpty(SceneManager.GetActiveScene().path))throw new Exception("Isolated Play required");string path="AUTO_QA/Evidence/"+take+".json";if(File.Exists(path))throw new Exception("Preserve evidence");var root=new GameObject("AUTO_QA warning contracts");var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.SetParent(root.transform);floor.transform.position=new Vector3(2000,499.5f,2000);floor.transform.localScale=new Vector3(300,1,300);var target=new GameObject("AUTO_QA warning target");target.transform.SetParent(root.transform);target.transform.position=new Vector3(2005,500,2000);target.AddComponent<GameSaveExcluded>();var hp=target.AddComponent<PlayerHealth>();hp.currentHealth=hp.maxHealth=1000;GameObject plane=null;var cases=new List<object>();string error=null;
 try{foreach(BombardinoBoss.AttackKind kind in Enum.GetValues(typeof(BombardinoBoss.AttackKind)))foreach(string stage in new[]{"telegraph","cross to attack","target loss","death"}){target.SetActive(true);plane=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Prefabs/Bosses/BombardinoCrocodilo/BombardinoCrocodilo.prefab"),new Vector3(2000,500,2000),Quaternion.identity,root.transform);plane.AddComponent<GameSaveExcluded>();var boss=plane.GetComponent<BombardinoBoss>();boss.enabled=false;boss.target=target.transform;Set(boss,"targetHealth",hp);Prop(boss,"FightActive",true);Set(boss,"acquireAt",999f);Set(boss,"protectPlayersAt",999f);Set(boss,"nextAttackAt",0f);Set(boss,"announcedPhase",2);Call(boss,"StartAttack",kind);Set(boss,"attackAt",stage=="cross to attack"?.1f:5f);Set(boss,"nextMarkerAt",0f);if(stage=="target loss")target.SetActive(false);if(stage=="death")plane.GetComponent<Health>().Kill();boss.Tick(1f/3f);var lines=(List<LineRenderer>)Get(boss,"markers");var snapshots=lines.Select(line=>{var p=new Vector3[line.enabled?line.positionCount:0];if(line.enabled)line.GetPositions(p);return new{enabled=line.enabled,count=line.positionCount,positions=p.Select(v=>new[]{v.x,v.y,v.z}).ToArray()};}).ToArray();cases.Add(new{kind=kind.ToString(),stage,state=boss.CurrentState.ToString(),boss.FightActive,boss.BombsReleased,boss.MissilesLaunched,boss.FlameZonesCreated,lines=snapshots});UnityEngine.Object.DestroyImmediate(plane);plane=null;foreach(var p in UnityEngine.Object.FindObjectsByType<BombardinoOrdnance>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(p.gameObject);}}
 catch(Exception e){error=e.ToString();}finally{if(plane)UnityEngine.Object.DestroyImmediate(plane);UnityEngine.Object.DestroyImmediate(root);foreach(var p in UnityEngine.Object.FindObjectsByType<BombardinoOrdnance>(FindObjectsSortMode.None))UnityEngine.Object.DestroyImmediate(p.gameObject);}File.WriteAllText(path,Newtonsoft.Json.JsonConvert.SerializeObject(new{error,cases},Newtonsoft.Json.Formatting.None));return new{error,caseCount=cases.Count};}
}